uk_res = {}
be_res = {}
pl_res = {}

for k in sorted(en_dict.keys()):
    if k in SLAVIC_MAP:
        uk_res[k], be_res[k], pl_res[k] = SLAVIC_MAP[k]
    else:
        # Fallback to existing or ru
        uk_res[k] = existing.get("uk", {}).get(k, ru_dict.get(k, en_dict[k]))
        be_res[k] = existing.get("be", {}).get(k, ru_dict.get(k, en_dict[k]))
        pl_res[k] = existing.get("pl", {}).get(k, en_dict[k])

out_data = {
    "uk": uk_res,
    "be": be_res,
    "pl": pl_res
}

with open("tools/translations_slavic.json", "w", encoding="utf-8") as out:
    json.dump(out_data, out, ensure_ascii=False, indent=2)

